/** Helper method to write a single double value as a JSON array and return its string representation. */
private String jsonArrayOf(double value) throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    jsonWriter.value(value);
    jsonWriter.endArray();
    jsonWriter.close();
