@Test
public void testMixedCaseLiterals_trueLiterals() throws IOException {
  JsonReader reader = createMixedCaseReader();
  assertThat(reader.nextBoolean())
      .named("First literal should be true (case‑insensitive)")
      .isTrue();
  assertThat(reader.nextBoolean())
      .named("Second literal (mixed case) should be true")
      .isTrue();
}

