public void testMixedCaseLiterals_falseLiterals() throws IOException {
  JsonReader reader = createMixedCaseReader();
  // Skip the true literals
  reader.nextBoolean();
  reader.nextBoolean();
  assertThat(reader.nextBoolean())
      .named("Third literal should be false")
      .isFalse();
  assertThat(reader.nextBoolean())
      .named("Fourth literal (mixed case) should be false")
      .isFalse();
}

