public void testMixedCaseLiterals_nullLiterals() throws IOException {
  JsonReader reader = createMixedCaseReader();
  // Skip the true and false literals
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();
  // First null literal
  reader.nextNull();
  // Verify the second null literal is present before consuming it
  assertThat(reader.peek())
      .named("Second literal should be NULL")
      .isEqualTo(JsonToken.NULL);
  // Second null literal
  reader.nextNull();
}

