public void testMixedCaseLiterals_endDocument() throws IOException {
  JsonReader reader = createMixedCaseReader();
  // Consume all literals
  reader.nextBoolean(); // True
  reader.nextBoolean(); // TruE
  reader.nextBoolean(); // False
  reader.nextBoolean(); // FALSE
  reader.nextNull();    // NULL
  reader.nextNull();    // nulL
  reader.endArray();
  assertThat(reader.peek())
      .named("Reader should be at END_DOCUMENT after array end")
      .isEqualTo(END_DOCUMENT);
}

