private JsonWriter setupTestNewJsonWriter_Custom(StringWriter writer) throws IOException {
  return new GsonBuilder()
      .disableHtmlEscaping()
      .generateNonExecutableJson()
      .setPrettyPrinting()
      .serializeNulls()
      .setLenient()
      .create()
      .newJsonWriter(writer);
}

