public void testReadAcrossBuffers() throws IOException {
    JsonReader reader = setupReaderForBuffer(buildBufferString());
    JsonToken token = reader.peek();
    assertThat(token).isEqualTo(JsonToken.NUMBER);
}

private static String buildBufferString() {
    StringBuilder sb = new StringBuilder("#");
    for (int i = 0; i < JsonReader.BUFFER_SIZE - 3; i++) {
        sb.append(' ');
    }
    sb.append("\n)]}'\n3");
    return sb.toString();
}

private static JsonReader setupReaderForBuffer(String json) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.setStrictness(Strictness.LENIENT);
    return reader;
}

