    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertEquals(
            "Link href attribute should be the relative path to the horoscopes page",
            "/entertainment/horoscopes",
            a.attr("href"));
    assertEquals(
            "Link abs:href attribute should resolve to the full URL of the horoscopes page",
            "http://www.news.com.au/entertainment/horoscopes",
