private static class ElementsSetup {
    final Document doc;
    final Element original;
    final Element clone;

    ElementsSetup(Document doc, Element original, Element clone) {
        this.doc = doc;
        this.original = original;
        this.clone = clone;
    }
}

private ElementsSetup createDocumentAndElements() {
    Document doc = Jsoup.parse("<div class=foo>Text</div>");
    Element original = doc.select("div").first();
    Element clone = doc.clone().select("div").first();
    return new ElementsSetup(doc, original, clone);
}

private void modifyOriginal(Element original) {
    original.removeClass("foo");
    original.text("None");
}

@Test
public void supportsClone_originalHasClassInitially() {
    ElementsSetup setup = createDocumentAndElements();
    assertTrue(setup.original.hasClass("foo"),
            "Original element should have class 'foo' before cloning");
}

